import {uid,dateKey,addDays,monday,minutes,endTime,overlap,unavailableOn,slotsOn,conflicts,load,moveTask,snapshotDay,seed,inboxTasks,findTask,tasksInSlot,placeTask,stashTask,deleteTask,restoreTask,suggestStart,pastMinutes,canSchedule,canPlaceInSlot} from './model.js?v=20261124-quick-backlog';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const API_BASE=globalThis.PARAVOZIKI_API_BASE||'';let sessionToken='';try{sessionToken=sessionStorage.getItem('paravoziki.session')||'';}catch{}
let lastDeletion=null,toastTimeout=null,draggedEntity=null,suppressPaletteClickUntil=0;let telegramConnection=null;let KEY='rhythm.v1';let account=null,revision=0,authMode='login',pendingPlan=null,syncBusy=false,syncTimeout=null,syncBlocked=false;let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed();}catch{state=seed();}
let view='week',week=monday(dateKey()),day=dateKey(),wizard=null,selectedCategory=null,blockFilter='week',inboxPeriod='all',inboxReason='all',remoteRevision=0,remoteBusy=false;
const days=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],fullDays=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
const cat=id=>state.categories.find(c=>c.id===id)||{name:'Без блока',color:'#888',tag:''};
const fmt=n=>`${Math.round(n/60*10)/10} ч`,dateFmt=k=>new Date(k+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const btn=(text,action,data='',cls='')=>`<button class="${cls}" data-action="${action}" ${data}>${text}</button>`;
function save(){if(!account)return;pendingPlan=structuredClone(state);cachePlan(true);clearTimeout(syncTimeout);syncTimeout=setTimeout(flushPlan,500);}
function cachePlan(dirty){try{localStorage.setItem(KEY,JSON.stringify({state,revision,dirty}));}catch{toast('Локальная резервная копия недоступна.');}}
function toast(text,undo=false){clearTimeout(toastTimeout);$('#toast').innerHTML=esc(text)+(undo?' '+btn('Отменить удаление','undo-delete','','small'):'');$('#toast').style.display='block';toastTimeout=setTimeout(()=>$('#toast').style.display='none',undo?20000:4500);}
function modal(title,body){$('#modal').innerHTML=`<h2>${title}</h2>${body}`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();wizard=null;}
function actions(extra=''){return `<div class="actions">${btn('Отмена','close')}${extra}</div>`;}
function field(label,input){return `<label>${label}${input}</label>`;}
function input(name,type='text',value='',attrs=''){return `<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;}
function select(name,options,value){return `<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;}
function categorySelect(value){return select('category',state.categories.map(c=>[c.id,c.name]),value);}
function render(){const previousScroll=$('.timeline-scroll'),scrollTop=previousScroll?.scrollTop,scrollLeft=previousScroll?.scrollLeft;const titles={week:'Неделя',day:'Мой день',results:'Итоги',settings:'Настройки',blocks:'Блоки',inbox:'Входящие',backlog:'Накопитель'};
$('#app').innerHTML=`<div class="layout"><header class="app-header"><div class="brand"><img src="logo.svg" alt="" width="45" height="40"><span>паровозики</span></div><nav aria-label="Основное меню">${Object.entries(titles).map(([id,t])=>btn(navLabel(id,t),'nav',`data-view="${id}"`,id===view?'active':'')).join('')}</nav><div class="header-account"><span class="account-email">${esc(account?.email||'')}</span>${btn('Выйти','logout','','small soft')}<div id="sync-status" class="small">План в вашем аккаунте</div></div></header><main class="main">${view==='week'?renderWagonYard():'<div class="train-banner"><img src="train.svg" alt="" aria-hidden="true"></div>'}${view==='week'?'':renderTopbar(titles[view])}<div id="remote-notice" role="status"></div>${({week:renderWeek,day:renderDay,results:renderResults,settings:renderSettings,blocks:renderBlocks,inbox:renderInbox,backlog:renderBacklog})[view]() }</main></div>`;updateClock();updateRemoteNotice();const timeline=$('.timeline-scroll');if(timeline){timeline.scrollTop=scrollTop??0;timeline.scrollLeft=scrollLeft??0;}}
function heading(title,sub,controls=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${controls}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,val,note])=>`<div class="stat"><span class="muted">${label}</span><strong>${val}</strong><small>${note}</small></div>`).join('')}</div>`;}
function renderWeek(){const dates=Array.from({length:7},(_,i)=>addDays(week,i)),ss=state.slots.filter(s=>dates.includes(s.date)),ts=state.tasks.filter(t=>dates.includes(t.date));let overs=0;for(const d of dates)for(const c of state.categories)overs+=load(state,c.id,d).overflow;const issues=conflicts(state).filter(c=>ss.some(s=>s.id===c.slot));return `<div class="week-layout"><section class="week-rail" aria-label="Панель недели">`+renderBacklogTray()+renderTopbar('Неделя')+heading('Неделя','Распределите время между важными направлениями.',btn('Шаблон недели','template')+btn('+ Добавить задачу','task','','primary'))+`</section><section class="week-content" aria-label="Календарь недели"><div class="calendar-toolbar">`+`<div class="week-tools"><div class="actions">${btn('←','week-prev','aria-label="Предыдущая неделя"')}<span class="week-label">${dateFmt(week)} — ${dateFmt(addDays(week,6))}</span>${btn('→','week-next','aria-label="Следующая неделя"')}</div><div class="actions">${btn('Текущая неделя','week-now')}${btn('Корректировка','adjust')+btn(`Входящие (${inboxTasks(state).length})`,'open-inbox')}</div></div>`+stats([['Время в блоках',fmt(ss.reduce((n,s)=>n+s.duration,0)),'Распределено на эту неделю'],['Запланировано',fmt(ts.reduce((n,t)=>n+t.estimate,0)),`${ts.length} задач в плане`],['Перегрузка',fmt(overs),overs?'Есть задачи для корректировки':'Всё помещается в блоки']])+`</div>`+(issues.length?`<div class="notice">${issues.map(i=>esc(i.text)).join('<br>')}</div>`:'')+renderTimeline(dates)+`</section></div>`;}
function slotCard(s){const c=cat(s.category),l=load(state,c.id,s.date),ts=tasksInSlot(state,s);return `<div class="block" data-slot-id="${s.id}" role="group" aria-label="${esc(c.name)} ${s.date} ${s.start}" style="--color:${c.color}"><div class="slot-time"><div class="time">${s.start}–${endTime(s.start,s.duration)}</div>${btn('×','delete-slot',`data-id="${s.id}" aria-label="Удалить интервал ${esc(c.name)}" title="Удалить интервал"`,'icon-button task-delete')}</div><div class="slot-heading">${btn(esc(c.name),'open-block',`data-id="${c.id}"`,'block-title block-link')}${btn('✎','slot',`data-id="${s.id}" data-date="${s.date}" aria-label="Изменить интервал ${esc(c.name)}" title="Изменить интервал"`,'icon-button interval-edit')}</div><div class="capacity ${l.overflow?'warn':''}">${l.planned} / ${l.budget} мин за день</div><div class="bar"><span style="--color:${l.overflow?'#c77c58':c.color};width:${l.budget?l.planned/l.budget*100:0}%"></span></div>${ts.map(compactTask).join('')}</div>`;}

function dateControl(){return `<input id="selected-day" type="date" value="${day}" aria-label="Выбрать день" style="width:auto">`;}
function renderDay(){const ts=state.tasks.filter(t=>t.date===day),ss=slotsOn(state,day).sort((a,b)=>a.start.localeCompare(b.start)),started=!!state.baselines[day];return heading('Один день. Один фокус.','Начните с одной задачи, остальное уже в плане.',dateControl()+btn('+ Задача','task','','primary'))+`<div class="cols"><div>${!started?`<div class="panel"><h2>Готовы начать день?</h2><p class="muted">Зафиксируем исходный план, чтобы вечером сравнить его с результатом.</p>${btn('Запустить день','start-day','','primary')}</div>`:`<p class="pill">Исходный план сохранён · ${state.baselines[day].tasks.length} задач</p>`}${ss.length?ss.map(s=>{const c=cat(s.category),l=load(state,c.id,day);return `<div class="panel" data-slot-id="${s.id}" style="border-top:3px solid ${c.color}"><div class="actions" style="justify-content:space-between"><h2>${btn(esc(c.name),'open-block',`data-id="${c.id}"`,'block-link')}</h2><span class="muted">${s.start}–${endTime(s.start,s.duration)}</span></div><p class="small ${l.overflow?'warn':'muted'}">План ${l.planned} мин · факт ${Math.round(l.actual)} мин · доступно ${l.budget} мин</p>${tasksInSlot(state,s).map(taskRow).join('')||'<div class="empty">В этом интервале пока нет задач</div>'}</div>`;}).join(''):'<div class="panel empty">На этот день ещё нет интервалов.<br>Добавьте их в плане недели.</div>'}${ts.filter(t=>!ss.some(s=>s.category===t.category)).length?`<div class="panel"><h2>Без интервала</h2>${ts.filter(t=>!ss.some(s=>s.category===t.category)).map(taskRow).join('')}</div>`:''}</div><div>${timerPanel()}<div class="panel"><h2>Оставить место для жизни</h2><p class="muted">Незапланированное дело тоже занимает время. Добавьте его, чтобы увидеть реальную нагрузку.</p>${btn('+ Записать дело','task')}<hr style="border:0;border-top:1px solid #e5e8df;margin:22px 0"><p class="small muted">Помодоро: 25 минут фокуса, затем предложение сделать перерыв. Таймер считает время по часам, в том числе при свёрнутой вкладке.</p></div></div></div>`;}
function taskRow(t){return `<div class="task" draggable="${!t.done}" data-drag-kind="task" data-task-id="${t.id}">${taskCheck(t)}<span class="dot" style="--color:${cat(t.category).color}"></span><div class="body ${t.done?'done':''}">${esc(t.title)}<small>${t.estimate} мин план · ${Math.round(t.actual)} мин факт</small></div><div class="actions">${!t.done&&t.date?btn('▶','focus',`data-id="${t.id}" aria-label="Начать ${esc(t.title)}"`,'soft'):''}${taskControls(t)}</div></div>`;}

function timerPanel(){const timer=state.timer,t=timer&&state.tasks.find(x=>x.id===timer.task);return `<div class="panel timer"><div class="eyebrow">Время фокуса</div><h2 style="margin-top:20px">${t?esc(t.title):'Выберите задачу'}</h2><div class="clock" id="clock">25:00</div><p class="muted small" id="timer-status">${timer?'Фокус-сессия':'Нажмите ▶ рядом с задачей'}</p><div class="actions">${timer?btn(timer.running?'Пауза':'Продолжить','timer-toggle','','primary')+btn('Завершить сессию','timer-stop'):''}</div></div>`;}
function renderBlocks(){
 const c=cat(selectedCategory||state.categories[0]?.id);selectedCategory=state.categories.find(x=>x.id===selectedCategory)?.id||state.categories[0]?.id;
 const today=dateKey(),start=week,end=addDays(start,6);
 const tasks=state.tasks.filter(t=>t.category===selectedCategory&&(blockFilter==='all'||(blockFilter==='today'?t.date===today:t.date>=start&&t.date<=end))).sort((a,b)=>a.date.localeCompare(b.date)||Number(a.done)-Number(b.done)||a.title.localeCompare(b.title,'ru'));
 const dates=[...new Set(tasks.map(t=>t.date))];const done=tasks.filter(t=>t.done).length;
 const period=blockFilter==='today'?'Сегодня, '+dateFmt(today):blockFilter==='week'?'Неделя: '+dateFmt(start)+' — '+dateFmt(end):'За всё время';
 return heading('Дела блока', 'Все задачи направления в одном месте.',btn('+ Добавить задачу','task','','primary'))+`<div class="actions block-tabs" aria-label="Выбор блока">${state.categories.map(x=>btn(`<span class="dot" style="--color:${x.color}"></span> ${esc(x.name)}`,'block-select',`data-id="${x.id}" aria-pressed="${x.id===selectedCategory}"`,x.id===selectedCategory?'primary':'')).join('')}</div><section class="panel"><div class="heading"><div><h2>${esc(cat(selectedCategory).name)}</h2><p class="subtitle">${period}</p></div><div class="actions" aria-label="Период задач">${[['today','Сегодня'],['week','Неделя'],['all','Все']].map(([key,label])=>btn(label,'block-filter',`data-filter="${key}" aria-pressed="${key===blockFilter}"`,key===blockFilter?'primary':'')).join('')}</div></div>${stats([['Задач',tasks.length,`${tasks.length-done} осталось · ${done} завершено`],['План',fmt(tasks.reduce((n,t)=>n+t.estimate,0)),'Оценка выбранных задач'],['Факт',fmt(tasks.reduce((n,t)=>n+t.actual,0)),'По этим задачам за всё время']])}${dates.map(d=>`<section class="block-date"><h3>${new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}${d===today?' · сегодня':''}</h3>${tasks.filter(t=>t.date===d).map(t=>`<div class="block-task">${taskRow(t)}<span class="pill ${!t.done&&!slotsOn(state,t.date).some(s=>s.category===t.category)?'warn':''}">${t.done?'Завершено':!slotsOn(state,t.date).some(s=>s.category===t.category)?'Нет интервала':'В плане'}</span></div>`).join('')}</section>`).join('')||`<div class="empty">${blockFilter==='all'?'В этом блоке пока нет задач.':'За выбранный период задач нет.'}<br>Добавьте задачу или выберите другой период.</div>`}</section>`;
}
function renderResults(){const baseline=state.baselines[day],original=baseline?.tasks||state.tasks.filter(t=>t.date===day);const planned=original.reduce((n,t)=>n+t.estimate,0),actual=state.sessions.filter(s=>s.date===day).reduce((n,s)=>n+s.minutes,0),moves=state.moves.filter(m=>m.from===day);const review=state.reviews[day]||{};return heading('Время без самообмана','Посмотрите на результат и отметьте, как вы себя чувствуете.',dateControl())+(!baseline?'<div class="notice">День ещё не запускался. Показан текущий план; исходный план не зафиксирован.</div>':'')+stats([['План на старте',fmt(planned),`${original.length} задач`],['Фактически',fmt(actual),'По завершённым фокус-сессиям'],['Перенесено',fmt(moves.reduce((n,m)=>n+m.minutes,0)),`${moves.length} переносов`]])+`<form id="review-form"><div class="review">${state.categories.map(c=>{const orig=original.filter(t=>t.category===c.id),done=orig.filter(t=>state.tasks.find(x=>x.id===t.id)?.done).length;const fact=state.sessions.filter(s=>s.date===day&&s.category===c.id).reduce((n,s)=>n+s.minutes,0);return `<div class="panel" style="border-top:3px solid ${c.color}"><h2>${esc(c.name)}</h2><p class="muted">${done} из ${orig.length} задач завершено · ${Math.round(fact)} мин фактически</p>${field('Насколько вы довольны результатом?',select(`rating-${c.id}`,[['','Без оценки'],['1','1 — совсем не довольна'],['2','2 — скорее не довольна'],['3','3 — нормально'],['4','4 — довольна'],['5','5 — очень довольна']],review.ratings?.[c.id]||''))}</div>`;}).join('')}</div><div class="panel"><h2>Что повлияло на день?</h2><p class="muted">${Math.abs(planned-actual)>=60?'План и факт заметно различаются. Можно записать причину.':'Комментарий поможет лучше спланировать следующую неделю.'}</p>${field('Причина',select('reason',[['','Не выбрана'],['hidden','Скрытые или незапланированные дела'],['complex','Задачи оказались сложнее'],['interruptions','Отвлечения'],['priorities','Изменились приоритеты'],['other','Другое']],review.reason||''))}${field('Комментарий',`<textarea name="comment" placeholder="Что стоит учесть в следующий раз?">${esc(review.comment||'')}</textarea>`)}<button class="primary">Сохранить итоги</button></div></form>`;}
function renderSettings(){return heading('Настроить под себя','Ваши блоки, ограничения и шаблон недели.')+`<div class="settings-grid"><section class="panel"><div class="heading"><h2>Ваши блоки</h2>${btn('+ Блок','category','','soft')}</div>${state.categories.map(c=>`<div class="row"><div><span class="dot" style="--color:${c.color}"></span> ${esc(c.name)}<small>#${esc(c.tag)}</small></div>${btn('Изменить','category',`data-id="${c.id}"`,'small')}</div>`).join('')}</section><section class="panel"><div class="heading"><h2>Занятое время</h2>${btn('+ Событие','unavailable','','soft')}</div><p class="muted small">Созвоны, курс и другие фиксированные события. Приложение проверяет пересечения с интервалами.</p>${state.unavailable.map(e=>`<div class="row"><div>${esc(e.title)}<small>${e.repeat==='weekly'?fullDays[e.weekday]+' · еженедельно':dateFmt(e.from)} · ${e.start}–${endTime(e.start,e.duration)}${e.until?' · до '+dateFmt(e.until):''}</small></div>${btn('×','delete-event',`data-id="${e.id}" aria-label="Удалить событие"`)}</div>`).join('')||'<p class="muted">Событий пока нет.</p>'}</section>${telegramPanel()}<section class="panel"><h2>Данные и шаблон</h2><p class="small muted">Аккаунт: ${esc(account?.email||'')}</p><p class="muted">План сохраняется в вашем аккаунте и доступен после входа на другом устройстве. Экспорт создаёт дополнительную резервную копию.</p><div class="actions">${btn('Экспорт JSON','export')}${btn('Импорт JSON','import')}</div><input type="file" id="import-file" accept="application/json" hidden><div class="row"><span class="muted small">Часовой пояс устройства</span><span class="small">${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</span></div><div class="row"><span>Повторяемая неделя</span>${btn('Настроить','template')}</div></section></div>`;}
function showTask(){wizard={step:0,title:'',category:view==='blocks'?(selectedCategory||state.categories[0]?.id):state.categories[0]?.id,estimate:30,date:view==='backlog'?null:view==='blocks'?dateKey():day};showWizard();}
function showWizard(){const w=wizard;let body=`<div class="steps">${[0,1,2,3,4].map(i=>`<span class="${i<=w.step?'on':''}"></span>`).join('')}</div>`;const titles=['Что нужно сделать?','В какой блок?','Сколько времени планируем?','На какой день?','Всё верно?'];if(w.step===0)body+=`<form id="wizard-title">${field('Название задачи',input('title','text',w.title,'required maxlength="240" autofocus'))}<div class="actions">${btn('Отмена','close')}<button class="primary">Дальше →</button></div></form>`;if(w.step===1)body+=`<div class="choices">${state.categories.map(c=>btn(`<span class="dot" style="--color:${c.color}"></span> ${esc(c.name)}`,'wizard-cat',`data-id="${c.id}"`)).join('')}</div>`;if(w.step===2)body+=`<div class="choices">${[15,30,45,60,90,120].map(n=>btn(n+' мин','wizard-duration',`data-minutes="${n}"`)).join('')}</div><form id="wizard-custom" style="margin-top:18px">${field('Или своя длительность, минуты',input('estimate','number',w.estimate,'min="1" max="1440" required'))}<button>Дальше →</button></form>`;if(w.step===3)body+=`<div class="choices">${btn('Сегодня','wizard-date',`data-date="${dateKey()}"`)}${btn('Завтра','wizard-date',`data-date="${addDays(dateKey(),1)}"`)}${btn('В накопитель — без даты','wizard-backlog')}</div><p class="muted small">Ближайшие семь дней</p><div class="choices">${Array.from({length:7},(_,i)=>{const d=addDays(dateKey(),i);return btn(`${fullDays[(new Date(d+'T12:00:00').getDay()+6)%7]}<br><small>${dateFmt(d)}</small>`,'wizard-date',`data-date="${d}"`);}).join('')}</div><form id="wizard-calendar" style="margin-top:18px">${field('Или конкретная дата',input('date','date',w.date,'required'))}<button>Выбрать дату →</button></form>`;if(w.step===4){const l=load(state,w.category,w.date);body+=`<div class="chat"><strong>${esc(w.title)}</strong><br>${esc(cat(w.category).name)} · ${w.estimate} мин<br>${w.date?dateFmt(w.date):'Накопитель · без даты'}</div>`+(w.date===null?'<p class="muted">Задача не занимает время в расписании. Её можно будет запланировать позже.</p>':l.budget-l.actual-l.remaining<w.estimate?`<div class="notice">${!l.budget?'В этот день у блока нет интервала.':'Задача превышает свободное время блока на '+Math.ceil(w.estimate-(l.budget-l.actual-l.remaining))+' мин.'} Можно вернуться к выбору даты или сохранить во «Входящие».</div>`:`<p class="muted">После добавления останется ${Math.floor(l.budget-l.actual-l.remaining-w.estimate)} мин.</p>`)+`<div class="actions">${btn('Изменить','wizard-reset')}${btn('Добавить задачу','wizard-save','','primary')}</div>`;}if(w.step>0)body+=`<div class="actions">${btn('Отмена','close')}${btn('← Назад','wizard-back')}</div>`;modal(titles[w.step],body);}
function showSlot(id,date,defaultCategory,defaultDuration){if(date<dateKey()){toast('Этот день уже прошёл. Выберите будущую дату.');return;}const s=state.slots.find(x=>x.id===id);modal(s?'Изменить интервал':'Новый интервал',`<form id="slot-form" data-id="${id||''}">${field('Блок',categorySelect(s?.category||defaultCategory))}${field('Дата',input('date','date',date,'required'))}${field('Начало',input('start','time',s?.start||futureStart(date,defaultDuration||120),'required'))}${field('Продолжительность, минуты',input('duration','number',s?.duration||defaultDuration||120,'required min="15" max="1440" step="15"'))}${actions((s?btn('Удалить','delete-slot',`data-id="${s.id}"`,'danger'):'')+'<button class="primary">Сохранить</button>')}</form>`);}
