function showTemplate(){modal('Шаблон недели',`<p class="muted">Сохраните интервалы открытой недели как шаблон. При применении задачи и существующие интервалы сохраняются; точные дубликаты не добавляются.</p><p>Открытая неделя: <strong>${dateFmt(week)} — ${dateFmt(addDays(week,6))}</strong></p><p class="muted">В шаблоне ${state.template.length} интервалов.</p><div class="actions">${btn('Отмена','close')}${btn('Сохранить эту неделю','template-save')}${btn('Применить к этой неделе','template-apply','','primary')}</div>`);}
function showMove(id){const t=findTask(state,id);modal(t.date?'Перенести задачу':'Назначить дату',`<p>${esc(t.title)}</p><form id="move-form" data-id="${id}">${field('Новая дата',input('date','date',t.date?addDays(t.date,1):dateKey(),'required'))}<p class="muted small">После переноса задача появится в своём блоке. Если места нет, она будет видна во «Входящих».</p>${actions('<button class="primary">Перенести</button>')}</form>`);}
