 if(d?.version!==1||!['categories','slots','tasks','template','unavailable','moves','sessions'].every(k=>Array.isArray(d[k]))||!d.baselines||Array.isArray(d.baselines)||!d.reviews||Array.isArray(d.reviews))return false;
